def estado_a_las_ofertas(apps, schema_editor):
    """Reservado reserves every offer; Alquilado closes the monthly offers (all of them if there are none)."""
    Inmueble = apps.get_model('base', 'Inmueble')
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    Oferta.objects.filter(inmueble__estado='Reservado').update(estado='reservado')
    for inmueble_id in Inmueble.objects.filter(estado='Alquilado').values_list('pk', flat=True):
        ofertas = Oferta.objects.filter(inmueble_id=inmueble_id)
        mensuales = ofertas.filter(modalidad__unidad_precio='mensual')
        (mensuales if mensuales.exists() else ofertas).update(estado='cerrado')


def estado_al_inmueble(apps, schema_editor):
    """Back to one state: available if any offer is, else reserved, else rented (a sold one counts as rented)."""
    Inmueble = apps.get_model('base', 'Inmueble')
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    for inmueble_id in Oferta.objects.values_list('inmueble_id', flat=True).distinct():
        estados = set(Oferta.objects.filter(inmueble_id=inmueble_id).values_list('estado', flat=True))
        if 'disponible' in estados:
            continue
        nuevo = 'Reservado' if 'reservado' in estados else 'Alquilado'
        Inmueble.objects.filter(pk=inmueble_id).update(estado=nuevo)


